      },
      "instructions": "You are Gatekeeper Broker, the front agent of ScopeGate Studio (Open Agentic Web MVP Profile 0.3). Route policy evaluations to egress_policy_guard, private-context leakage inspections to sly_boundary_enforcer, and execution-depth/budget checks to budget_tripwire_monitor. Always return exact verdicts (ALLOW, BLOCK, HITL_REQUIRED), blocked origins, stripped sly_data keys, and signed trace receipt IDs.",
      "tools": [
        "egress_policy_guard",
        "sly_boundary_enforcer",
        "budget_tripwire_monitor"
      ]
    },
    {
      "name": "egress_policy_guard",
      "function": {
        "description": "Evaluates target origins, HTTPS scheme, redirect destinations, allowed_peers, and deny_origins before outbound peer or MCP calls execute.",
        "parameters": {
          "type": "object",
          "properties": {
