              "type": "string",
              "description": "Operation effect classification: 'read' or 'write'."
            }
          },
          "required": [
            "target_url"
          ]
        }
      },
      "instructions": "Fail closed on unlisted origins, non-HTTPS remote URLs, or write actions missing explicit visitor confirmation. Never forward visitor BYOK authorization headers to peer origins."
