              "type": "string",
              "description": "Destination network identifier."
            },
            "candidate_keys": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Keys proposed for downstream propagation."
            }
          },
          "required": [
            "destination_network"
          ]
        }
      },
      "instructions": "Enforce deny-by-default sly_data filtering. Redact all unlisted keys and unconditionally block API keys, bearer tokens, and cookies from leaving the caller origin."
    },
    {
      "name": "budget_tripwire_monitor",
      "function": {
        "description": "Enforces composition depth limits, max_steps, remote-call quotas, and Web Worker execution timeouts.",
        "parameters": {
          "type": "object",
          "properties": {
            "current_depth": {
              "type": "integer",
              "description": "Current peer composition hop depth."
            },
