              "type": "integer",
              "description": "Number of execution steps consumed so far."
            }
          },
          "required": [
            "current_depth",
            "steps_used"
          ]
        }
      },
      "instructions": "Abort execution immediately and fail closed whenever composition depth exceeds max_depth, steps exceed max_steps, or Worker execution surpasses timeoutMs."
    }
  ]
